<?php
namespace Tests\Feature;use App\Models\{About,Contact,User};use Database\Seeders\DatabaseSeeder;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class AboutContactAdminTest extends TestCase{use RefreshDatabase;private function login():void{$this->seed(DatabaseSeeder::class);$this->actingAs(User::where('email','superadmin@admin.com')->firstOrFail());}
 public function test_about_english_crud_and_filter():void{$this->login();$this->post(route('abouts.store'),['key'=>'story','image_path'=>'story.jpg','en'=>['title'=>'Our Story','description'=>'Company history']])->assertRedirect();$about=About::where('key','story')->firstOrFail();$this->get(route('abouts.index',['q'=>'Our Story']))->assertOk()->assertSee('Our Story');$this->put(route('abouts.update',$about),['key'=>'story','image_path'=>'updated.jpg','en'=>['title'=>'Updated Story','description'=>'Updated history']])->assertRedirect();$this->assertDatabaseHas('about_translations',['about_id'=>$about->id,'title'=>'Updated Story']);$this->delete(route('abouts.destroy',$about))->assertRedirect();$this->assertDatabaseMissing('abouts',['id'=>$about->id]);}
 public function test_contact_crm_filters_opens_marks_read_and_deletes():void{$this->login();$contact=Contact::create(['name'=>'John Smith','phone'=>'555-0101','message'=>'Private tour request','is_read'=>false]);$this->get(route('contacts.index',['q'=>'John','read'=>'0']))->assertOk()->assertSee('Private tour request')->assertSee('Unread');$this->get(route('contacts.show',$contact))->assertOk()->assertSee('John Smith');$this->assertDatabaseHas('contacts',['id'=>$contact->id,'is_read'=>1]);$this->delete(route('contacts.destroy',$contact))->assertRedirect();$this->assertSoftDeleted($contact);}
 public function test_about_and_contacts_require_permissions():void{$user=User::factory()->create();$this->actingAs($user)->get(route('abouts.index'))->assertForbidden();$this->get(route('contacts.index'))->assertForbidden();}
}
